import { NextRequest, NextResponse } from "next/server";
import { requireCurrentUser } from "@/lib/users";
import { summarizeNote } from "@/lib/summarize";

export async function POST(request: NextRequest) {
  let user;
  try {
    user = await requireCurrentUser();
  } catch {
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: "Request body must be JSON." },
      { status: 400 }
    );
  }

  const text = (body as { text?: unknown } | null)?.text;
  if (typeof text !== "string" || !text.trim()) {
    return NextResponse.json(
      { error: "`text` is required and must be a non-empty string." },
      { status: 400 }
    );
  }

  try {
    const summary = await summarizeNote(text);
    return NextResponse.json({ summary, summarizedFor: user.id });
  } catch (err) {
    console.error("[/api/summarize] failed:", err);
    const message = err instanceof Error ? err.message : "Failed to summarize note.";
    const status = message.includes("ANTHROPIC_API_KEY") ? 500 : 502;
    return NextResponse.json({ error: message }, { status });
  }
}

